INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6259256, 925673, 112828, '<td valign="top">Well, at least it''s been rotated to be straight...<br/> <br/>I''m usually OK with similar entries, but in this case I think you missed a chance to show some creativity..  This could have been funny if she was doing something quite different/facing the camera, etc...</td>', 'Well, at least it''s been rotated to be straight... I''m usually OK with similar entries, but in this case I think you missed a chance to show some creativity..  This could have been funny if she was doing something quite different/facing the camera, etc...', '2010-12-22 00:28:47.000000', NULL, 1),
(6259310, 926162, 83313, '<td valign="top">I didn''t even think of such an approach to this subject, but it suits.</td>', 'I didn''t even think of such an approach to this subject, but it suits.', '2010-12-22 01:16:46.000000', NULL, 1),
(6259311, 926202, 83313, '<td valign="top">Very cool use of the reflections. I actually had to look to find the camera in your hands.</td>', 'Very cool use of the reflections. I actually had to look to find the camera in your hands.', '2010-12-22 01:18:23.000000', NULL, 1),
(6259312, 925404, 83313, '<td valign="top">Interesting subject, since <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=103142" rel="nofollow" target="_blank">VaWendy</a> did well with a photo of a ceiling fan, it should be interesting to see how this performs. Nice and sharp with an interesting play of light.</td>', 'Interesting subject, since  VaWendy did well with a photo of a ceiling fan, it should be interesting to see how this performs. Nice and sharp with an interesting play of light.', '2010-12-22 01:20:22.000000', NULL, 1),
(6259347, 925935, 43088, '<td valign="top">Nicely executed and fits the challenge well.</td>', 'Nicely executed and fits the challenge well.', '2010-12-22 03:49:00.000000', NULL, 1),
(6259349, 926202, 43088, '<td valign="top">Lots of complexities which makes it very intresting. Glad you went with BW on this one.  Without seeing how it looked in the original, some things may be distracting in color. I like the double reflections.</td>', 'Lots of complexities which makes it very intresting. Glad you went with BW on this one.  Without seeing how it looked in the original, some things may be distracting in color. I like the double reflections.', '2010-12-22 03:50:29.000000', NULL, 1),
(6259350, 925252, 43088, '<td valign="top">Lovely colors and tones.</td>', 'Lovely colors and tones.', '2010-12-22 03:50:52.000000', NULL, 1),
(6259351, 925404, 43088, '<td valign="top">Interesting graphic image.</td>', 'Interesting graphic image.', '2010-12-22 03:51:38.000000', NULL, 1),
(6259352, 925343, 43088, '<td valign="top">Doing a wedding shoot?  Perhaps a bit more of an angle on the rings would be interesting (more of a 45 degree?) Nice concept.</td>', 'Doing a wedding shoot?  Perhaps a bit more of an angle on the rings would be interesting (more of a 45 degree?) Nice concept.', '2010-12-22 03:53:14.000000', NULL, 1),
(6259353, 926126, 43088, '<td valign="top">They look ghostly in the reflection!</td>', 'They look ghostly in the reflection!', '2010-12-22 03:53:38.000000', NULL, 1),
(6259354, 925849, 43088, '<td valign="top">I considered doing something similar. Wonder if you could have been a bit more left and had the figure and the tree a bit more in the frame of the windows?  I feel the tree in particular was cut off a bit. Nice job on the tough exposure.</td>', 'I considered doing something similar. Wonder if you could have been a bit more left and had the figure and the tree a bit more in the frame of the windows?  I feel the tree in particular was cut off a bit. Nice job on the tough exposure.', '2010-12-22 03:55:03.000000', NULL, 1),
(6259355, 925908, 43088, '<td valign="top">Very nicely lit.</td>', 'Very nicely lit.', '2010-12-22 03:55:36.000000', NULL, 1),
(6259356, 926124, 43088, '<td valign="top">She (?) seems a bit more like on the inside (of the bus) looking out rather than on the outside looking in to me.</td>', 'She (?) seems a bit more like on the inside (of the bus) looking out rather than on the outside looking in to me.', '2010-12-22 03:56:46.000000', NULL, 1),
(6259357, 925387, 43088, '<td valign="top">Hmm. "Outside looking in?" Maybe not. Interesting sky though.</td>', 'Hmm. "Outside looking in?" Maybe not. Interesting sky though.', '2010-12-22 03:57:41.000000', NULL, 1),
(6259358, 926168, 43088, '<td valign="top">Interesting use of negative space. I think perhaps cropping a bit more off the top (no0t a lot- maybe as much as the width of the vertical post in the window) might give it better proportion in my opinion.</td>', 'Interesting use of negative space. I think perhaps cropping a bit more off the top (no0t a lot- maybe as much as the width of the vertical post in the window) might give it better proportion in my opinion.', '2010-12-22 04:00:11.000000', NULL, 1),
(6259360, 926118, 43088, '<td valign="top">A lovely shot but the blur of what is in the man''s hand is a bit distracting.</td>', 'A lovely shot but the blur of what is in the man''s hand is a bit distracting.', '2010-12-22 04:02:08.000000', NULL, 1),
(6259361, 925673, 43088, '<td valign="top">Wondering if I have seen this one before?</td>', 'Wondering if I have seen this one before?', '2010-12-22 04:02:53.000000', NULL, 1),
(6259362, 926234, 43088, '<td valign="top">Interesing shot- especially the expression.  Based on the window frame, it appears to be on the inside looking out though?  I guess I trust you on that.</td>', 'Interesing shot- especially the expression.  Based on the window frame, it appears to be on the inside looking out though?  I guess I trust you on that.', '2010-12-22 04:04:15.000000', NULL, 1),
(6259363, 925565, 43088, '<td valign="top">Tough one to score. Interesting colors and patterns.  Can we determine if it meets the category of "outside looking in"?  There does appear to be blue reflections that seem to be outside of a window so I guess, yes.</td>', 'Tough one to score. Interesting colors and patterns.  Can we determine if it meets the category of "outside looking in"?  There does appear to be blue reflections that seem to be outside of a window so I guess, yes.', '2010-12-22 04:06:16.000000', NULL, 1),
(6259364, 925666, 43088, '<td valign="top">Apropriate use of the tones to go with your title. I do find the blury portion of the window to be quite distracting though. I know that was probably not your fault but the window of the shop.</td>', 'Apropriate use of the tones to go with your title. I do find the blury portion of the window to be quite distracting though. I know that was probably not your fault but the window of the shop.', '2010-12-22 04:08:43.000000', NULL, 1),
(6259365, 926191, 43088, '<td valign="top">This is pretty cool.  The reflection of the gumballs on the sides of the bowl add motion to it.</td>', 'This is pretty cool.  The reflection of the gumballs on the sides of the bowl add motion to it.', '2010-12-22 04:09:36.000000', NULL, 1),
(6259366, 926161, 43088, '<td valign="top">I like the shapes and the texture. High creativity scores. Does it fit the challenge?  Probably depends on how the viewer looks at it.   It does seem to draw you into the "V" so we do seem to be looking into something.</td>', 'I like the shapes and the texture. High creativity scores. Does it fit the challenge?  Probably depends on how the viewer looks at it.   It does seem to draw you into the "V" so we do seem to be looking into something.', '2010-12-22 04:11:44.000000', NULL, 1),
