(6259397, 925982, 43088, '<td valign="top">Very nice black and white. Makes one wonder just what is going on here.</td>', 'Very nice black and white. Makes one wonder just what is going on here.', '2010-12-22 04:35:16.000000', NULL, 1),
(6259398, 926235, 43088, '<td valign="top">Facinating. The more you look at it the more you start to see in it.</td>', 'Facinating. The more you look at it the more you start to see in it.', '2010-12-22 04:37:20.000000', NULL, 1),
